    ["snmp_ratio_descr"] = "Flow/SNMP 比率的計算方法是將使用流量獲得的總介面流量除以透過 SNMP 讀取的同一介面的總流量。由於以流量為基礎的分析不會計入非 IP 流量和第 2 層標頭，<br>典型比率介於 0.8 到 0.9 之間（也就是說，透過 SNMP 觀察到的接收流量中，有 90%% 已回報於流量資料）。<br>比率會根據最近 5 分鐘的流量計算，因為 SNMP 會每 5 分鐘定期輪詢一次。只有符合以下條件時才會計算比率",
