        ["note_2"] = "連接埠：以逗號分隔的連接埠清單（或連接埠範圍）；如果為空，則將考慮所有主機連接埠。如果 ntopng 知道指定的連接埠，請按一下“載入開放連接埠”按鈕，用已知的主機伺服器連接埠填充“連接埠”欄位。",
        ["note_3"] = "掃描類型：選擇特定的漏洞掃描類型。",
