    ["note_drops_sflow"] = "丟棄僅針對 sFlow 顯示，因為 NetFlow 不會報告它們。<br><A HREF=https://www.ietf.org/rfc/rfc3176.txt>sFlow</A> drops 指的是 sFlow 代理偵測到標記為要取樣的封包由於缺乏資源而被放棄的次數。丟棄計數器報告自代理上次重設以來偵測到的丟棄總數。一個高的丟棄率表明管理代理無法以硬體產生的速度來處理樣本。增加 sFlow 取樣率將減少丟棄率。注意：一個不能偵測到丟包的代理將總是報告為零。",
    ["note_lifetime_timeout"] = "無論流量持續時間如何，活動時間超過指定最大值 <A HREF=https://www.ntop.org/guides/nprobe/cli_options.html?highlight=maximum%20flow%20lifetime>lifetime</A> 的流量將被視為已過期，並將被髮出（nProbe -t 選項）",
    ["note_packets"] = "在乙太網網路中，每個封包都有一個 <A HREF=\"https://en.wikipedia.org/wiki/Ethernet_frame\">24 位元組的開銷</A> [前導（7 位元組）,幀開始（1 位元組）、CRC（4 個位元組）和 <A HREF=\"http://en.wikipedia.org/wiki/Interframe_gap\">IFG</A>（12 個位元組）]。 此類開銷需要計入介面流量，但不會新增到 IP 位址之間交換的流量中。 這是因為此類資料會增加介面負載，但無法計入主機交換的流量中，因此預計主機和介面流量值之間的差異很小。",
