    ["toggle_top_sites_description"] = "啟用本機主機存取網站排行的建立。排行透過<a href=\"%{url}\">啟發式演算法</a>產生，每個本機主機最多保留 20 個網站。該演算法完全執行於記憶體中，無需磁碟互動。存取網站排行每 5 分鐘清理一次。可透過定期輪詢主機詳細資訊頁面中的 JSON <i class=\"fas fa-download fa-sm\"></i> 下載連結，為每個本機主機建立歷史存取網站存檔。支援的網站應用通訊協定包括：TLS、QUIC、HTTP 和 DNS。",
